pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes32 public constant EXPECTED_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    function setUp() public {
        // Deploy the reference C (the file under test is the buggy version when this test is used for mutant detection,
        // but the test must pass on the reference C itself, which returns IMPLEMENTATION_SLOT).
        c = new C();
    }

    function testFuzz_property(uint256 randomInput) public {
        // randomInput is unused but ensures the fuzzer runs the test with fuzzed values.
        bytes32 returnedSlot;
        try c.proxiableUUID() returns (bytes32 slot) {
            returnedSlot = slot;
        } catch {
            // The reference implementation does not revert in proxiableUUID when called directly
            // (notDelegated modifier is satisfied because address(this) == __self).
            revert("proxiableUUID should not revert when called directly");
        }
        // The general property: the returned slot MUST be IMPLEMENTATION_SLOT for the reference C.
        assertTrue(returnedSlot == EXPECTED_SLOT, "Wrong proxiableUUID slot");
    }
}

