import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 kink, uint256 slope0, uint256 slope1) public {
        // 1. Restrict to admissible kink values: must be < 1e27 and > 0 to not revert on slope setting
        bound(kink, 1, 1e27 - 1);
        // slopes don't need further bounds for this test
        address admin = address(0xBEEF);
        address unauthorized = address(0xCAFE);
        // 2. Deploy an adversarial access control helper that denies access to unauthorized
        DenyAccessControl deny = new DenyAccessControl();
        // 3. Initialize C with the adversarial helper's address
        c.initialize(address(deny));
        // 4. Now call a protected function (setSlopes) as unauthorized caller
        C.SlopeData memory sd = C.SlopeData({kink: kink, slope0: slope0, slope1: slope1});
        vm.prank(unauthorized);
        // Reference: should revert (access denied); Bug: succeeds because access check is never set up
        bool reverted;
        try c.setSlopes(address(0x123), sd) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}

// Adversarial access control that always returns false when called from an unauthorized address
contract DenyAccessControl {
    function checkAccess(bytes4, address, address caller) external view returns (bool) {
        return caller == address(0xBEEF);
    }
}

