pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        vm.assume(caller != address(0));
        vm.assume(asset != address(0));
        // ensure slopes are valid (kink < 1e27 and != 0)
        vm.assume(kink > 0 && kink < 1e27);
        // initialize c with a non-zero admin that later does not grant access, so only initialization matters
        c.initialize(address(0xdead));
        // try to call setSlopes from a fuzzed non-zero caller
        vm.prank(caller);
        bool success;
        try c.setSlopes(asset, IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            success = true;
        } catch {
            success = false;
        }
        // The reference must succeed for caller==address(0xdead) (the access control) and fail for others.
        // The mutant sets access control to zero, causing EVERY non-zero caller to be denied access.
        // A universal property: if caller == c's access control, success must be true; otherwise success must be false.
        // Since the mutant breaks this by making all calls fail, we can assert that success is false for callers not equal to the admin,
        // which the reference always satisfies, but the mutant violates for the admin caller itself.
        // Simpler: the reference access control is address(0xdead). In the buggy version it is address(0).
        // For the fuzzer to find a violation, we need a property that holds for ALL inputs on the reference and fails on the mutant.
        // Property: After initialization, if the caller is the same as the access control, success must be true.
        bool isAdmin = (caller == address(0xdead));
        assertTrue(isAdmin ? success : !success);
    }
}

